const terrainDefs={grass:{name:'Meadow',icon:'❧',desc:'Paint fertile green ground. Free.'},path:{name:'Road',icon:'⌁',desc:'Connect your settlement and resource areas. 1 gold per tile.'},water:{name:'Water',icon:'≈',desc:'Carve lakes and rivers. Water blocks walking; build bridges across it.'},stone:{name:'Rocky ground',icon:'◆',desc:'Shape crags, mountains and mining districts.'},sand:{name:'Sand',icon:'∴',desc:'Paint beaches and desert lands.'},ash:{name:'Ashlands',icon:'☷',desc:'Paint a bleak frontier for dangerous enemies.'},wild:{name:'Wilderness',icon:'☠',desc:'PvP enabled. Death risks carried items. Paint an area, then place valuable rewards.'},safe:{name:'Safe zone',icon:'✧',desc:'Remove Wilderness status. Normal gravestone rules apply.'}};
