function setMode(mode){const wasBuilding=buildingMode;buildingMode=mode==='build';paused=buildingMode;accumulator=0;if(wasBuilding&&!buildingMode){endStroke();down.clear();pinch=null;pendingPlacement=null;if($('build-confirm').open)$('build-confirm').close();history=[];future=[];save();}else if(!wasBuilding&&buildingMode){history=[];future=[];}$('game').classList.toggle('building-mode',buildingMode);$('build-controls').hidden=!buildingMode;r.buildingMode=buildingMode;$('build-tray').hidden=!buildingMode;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===mode));if(!buildingMode)clearTool();r.follow=null;r.resize();hud();}
